import React, { useEffect, useMemo, useState } from "react";
import { Link } from "wouter";
import { ArrowLeft, Check, Download, FileText, MapPin, Package, Pencil, Plus, Settings2, Store, Trash2, Upload, Users } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Checkbox } from "@/components/ui/checkbox";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { toast } from "sonner";
import { trpc } from "@/lib/trpc";
import { 解析批次CSV列, 取得員工列操作狀態 } from "../../../shared/adminRules";

const shellClass = "min-h-screen bg-[radial-gradient(circle_at_top_left,#f7eadc,transparent_42%),linear-gradient(135deg,#fbf8f2,#efe5d8)] p-4 text-[#3e2a1f] md:p-8";
const cardClass = "border-[#eadfd5] bg-[#fffdf9] shadow-sm";
const 補齊門市代號 = (value: string) => value.replace(/\D/g, "").slice(0, 5).padStart(5, "0");
type Store = { id: number; storeCode: string; name: string; address: string };
type Item = { id: number; materialCode: string; name: string; unitPrice: string | number; largeUnit: string; smallUnit: string; conversionRatio: number; active: boolean };
type Employee = { id: number; employeeNo: string; name: string; role: "admin" | "staff"; active: boolean };
type Template = { id: number; type: "purchase" | "return" | "scrap" | "count"; name: string; itemIds: string; active: boolean };

function 下載CSV(filename: string, rows: string[][]) { const csv = rows.map(row => row.map(value => `"${String(value ?? "").replaceAll('"', '""')}"`).join(",")).join("\\n"); const blob = new Blob(["\\ufeff" + csv], { type: "text/csv;charset=utf-8" }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = filename; link.click(); URL.revokeObjectURL(url); }
function 顯示日期與星期(日期時間: string) { const date = 日期時間.slice(0, 10); if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(date)) return 日期時間; const weekday = ["星期日", "星期一", "星期二", "星期三", "星期四", "星期五", "星期六"][new Date(`${date}T00:00:00`).getDay()]; return `${date}（${weekday}）${日期時間.length > 10 ? 日期時間.slice(10) : ""}`; }
function 解析CSV(text: string) { return 解析批次CSV列(text); }
function AdminOnly({ children }: { children: React.ReactNode }) { let isAdmin = false; try { const session = JSON.parse(localStorage.getItem("食包材登入") || "null"); isAdmin = session?.role === "管理員" || session?.role === "admin"; } catch { isAdmin = false; } return isAdmin ? <>{children}</> : <Layout title="無權限" description="此設定頁僅限管理員使用。"><Card className={cardClass}><CardContent className="p-8 text-center"><p className="text-[#806653]">請使用管理員工號登入後再進入此頁面。</p><Link href="/"><Button className="mt-4 bg-[#70452d]">返回登入</Button></Link></CardContent></Card></Layout>; }

function Layout({ title, description, children }: { title: string; description: string; children: React.ReactNode }) {
  return <main className={shellClass}><div className="mx-auto max-w-6xl"><div className="mb-6 flex flex-col gap-4 md:flex-row md:items-end md:justify-between"><div><div className="mb-3 flex flex-wrap items-center gap-4"><Link href="/"><Button variant="ghost" className="px-0 text-[#70452d]"><ArrowLeft className="mr-2 h-4 w-4" />返回主系統</Button></Link><Link href="/admin/settings"><Button variant="link" className="px-0 text-[#9b6257]">返回後台管理</Button></Link></div><p className="text-sm text-[#a28672]">後台設定</p><h1 className="mt-1 text-3xl font-semibold">{title}</h1><p className="mt-2 text-[#806653]">{description}</p></div><div className="rounded-2xl bg-[#70452d] p-3 text-[#f9ead6]"><Settings2 className="h-6 w-6" /></div></div>{children}</div></main>;
}

function StoreChecks({ stores, selected, onChange }: { stores: Store[]; selected: number[]; onChange: (ids: number[]) => void }) {
  return <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{stores.map(store => <label key={store.id} className="flex items-center gap-2 rounded-lg bg-[#faf3eb] p-2 text-sm"><Checkbox checked={selected.includes(store.id)} onCheckedChange={checked => onChange(checked ? [...selected, store.id] : selected.filter(id => id !== store.id))} />{store.storeCode}・{store.name}</label>)}</div>;
}

export function AdminSettingsHome() {
  const auditCount = trpc.admin.listAuditLogs.useQuery();
  const links = [{ href: "/admin/item-summary", title: "食包材彙總表", desc: "查看所有貨物品項與門市設定，未分派門市的品項也會保留", icon: Package }, { href: "/admin/items", title: "食包材品項設定", desc: "依門市管理品項、單價、大小值與換算比例", icon: Package }, { href: "/admin/employees", title: "員工與權限", desc: "管理員工工號、角色與可使用門市", icon: Users }, { href: "/admin/templates", title: "多品項預設表單設定", desc: "依門市設定進貨、退貨、報廢與盤點預設品項", icon: Settings2 }, { href: "/admin/stores", title: "門市管理", desc: "建立門市、地址與員工門市歸屬", icon: Store }, { href: "/admin/login-brand", title: "設定登入頁面", desc: "上傳或替換公司 Logo，並修改登入頁顯示的公司名稱", icon: Pencil }, { href: "/admin/audit", title: "完整操作稽核紀錄", desc: "查詢不可刪除的操作紀錄並依條件匯出", icon: FileText }, { href: "/admin/inventory-timeline", title: "庫存異動時間軸", desc: "依日期、員工與門市追蹤庫存及工作頁異動", icon: FileText }];
  return <Layout title="後台管理" description="請選擇要管理的設定項目。"><div className="grid gap-4 sm:grid-cols-2">{links.map(({ href, title, desc, icon: Icon }) => <Link key={href} href={href}><Card className={`${cardClass} h-full transition hover:-translate-y-0.5 hover:shadow-md`}><CardContent className="flex items-start gap-4 p-6"><div className="rounded-2xl bg-[#f2e4d5] p-3 text-[#70452d]"><Icon className="h-6 w-6" /></div><div><div className="flex flex-wrap items-center gap-2"><h2 className="font-semibold">{title}</h2>{href === "/admin/audit" && <span className="rounded-full bg-[#f2e4d5] px-2 py-0.5 text-xs font-semibold text-[#70452d]">{auditCount.data?.length ?? 0} 筆</span>}</div><p className="mt-2 text-sm leading-6 text-[#806653]">{desc}</p><p className="mt-4 text-sm font-medium text-[#9b6257]">進入設定 →</p></div></CardContent></Card></Link>)}</div></Layout>;
}

export function AuditLogsPage() {
  const employees = trpc.admin.listEmployees.useQuery(); const stores = trpc.admin.listAllStores.useQuery();
  const [startDate, setStartDate] = useState(""); const [endDate, setEndDate] = useState(""); const [employeeNo, setEmployeeNo] = useState(""); const [storeId, setStoreId] = useState(""); const [action, setAction] = useState("");
  const input = useMemo(() => ({ 開始日期: startDate || undefined, 結束日期: endDate || undefined, 員工工號: employeeNo || undefined, 門市編號: storeId ? Number(storeId) : undefined, 動作: action || undefined }), [startDate, endDate, employeeNo, storeId, action]);
  const logs = trpc.admin.listAuditLogs.useQuery(input); const rows = (logs.data ?? []) as Array<Record<string, unknown>>;
  const [sortKey, setSortKey] = useState("操作時間"); const [sortDirection, setSortDirection] = useState<"asc" | "desc">("desc");
  const sortedRows = useMemo(() => [...rows].sort((a, b) => { const left = String(a[sortKey] ?? ""); const right = String(b[sortKey] ?? ""); const result = left.localeCompare(right, "zh-Hant"); return sortDirection === "asc" ? result : -result; }), [rows, sortKey, sortDirection]);
  const clearFilters = () => { setStartDate(""); setEndDate(""); setEmployeeNo(""); setStoreId(""); setAction(""); };
  const toggleSort = (key: string) => { if (sortKey === key) setSortDirection(current => current === "asc" ? "desc" : "asc"); else { setSortKey(key); setSortDirection("asc"); } };
  const sortLabel = sortDirection === "asc" ? "升冪" : "降冪";
  const exportLogs = () => 下載CSV(`操作稽核紀錄_${new Date().toISOString().slice(0, 10)}.csv`, [["操作時間", "員工工號", "員工姓名", "門市編號", "動作", "內容", "異動前", "異動後"], ...sortedRows.map(log => [String(log.操作時間 ?? ""), String(log.員工工號 ?? ""), String(log.員工姓名 ?? ""), String(log.門市編號 ?? ""), String(log.動作 ?? ""), String(log.內容 ?? ""), String(log.異動前 ?? ""), String(log.異動後 ?? "")])]);
  return <AdminOnly><Layout title="完整操作稽核紀錄" description="此紀錄只會新增，不會因刪除單據或其他資料而移除；僅管理員可以查詢與匯出。"><div className="space-y-6"><Card className={cardClass}><CardContent className="grid gap-4 p-5 md:grid-cols-4"><div><label className="mb-1 block text-sm font-semibold text-[#70452d]">開始日期</label><Input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} /></div><div><label className="mb-1 block text-sm font-semibold text-[#70452d]">結束日期</label><Input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} /></div><div><label className="mb-1 block text-sm font-semibold text-[#70452d]">操作員工</label><Select value={employeeNo || "全部"} onValueChange={value => setEmployeeNo(value === "全部" ? "" : value)}><SelectTrigger><SelectValue placeholder="全部員工" /></SelectTrigger><SelectContent><SelectItem value="全部">全部員工</SelectItem>{(employees.data ?? []).map(employee => <SelectItem key={employee.employeeNo} value={employee.employeeNo}>{employee.employeeNo}・{employee.name}</SelectItem>)}</SelectContent></Select></div><div><label className="mb-1 block text-sm font-semibold text-[#70452d]">操作門市</label><Select value={storeId || "全部"} onValueChange={value => setStoreId(value === "全部" ? "" : value)}><SelectTrigger><SelectValue placeholder="全部門市" /></SelectTrigger><SelectContent><SelectItem value="全部">全部門市</SelectItem>{(stores.data ?? []).map(store => <SelectItem key={store.id} value={String(store.id)}>{store.storeCode}・{store.name}</SelectItem>)}</SelectContent></Select></div><div><label className="mb-1 block text-sm font-semibold text-[#70452d]">操作動作</label><Select value={action || "全部"} onValueChange={value => setAction(value === "全部" ? "" : value)}><SelectTrigger><SelectValue placeholder="全部動作" /></SelectTrigger><SelectContent><SelectItem value="全部">全部動作</SelectItem><SelectItem value="新增">新增</SelectItem><SelectItem value="修改">修改</SelectItem><SelectItem value="啟用">啟用</SelectItem><SelectItem value="停用">停用</SelectItem></SelectContent></Select></div></CardContent></Card><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><p className="text-sm text-[#806653]">目前篩選結果：{rows.length} 筆{startDate || endDate ? `，日期 ${startDate || "不限"} 至 ${endDate || "不限"}` : "，全部日期"}{employeeNo ? `，員工 ${employeeNo}` : "，全部員工"}{storeId ? `，門市 ${(stores.data ?? []).find(store => String(store.id) === storeId)?.name ?? storeId}` : "，全部門市"}{action ? `，動作 ${action}` : "，全部動作"}</p><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={clearFilters} disabled={!startDate && !endDate && !employeeNo && !storeId && !action} className="border-[#dfcbb8] text-[#70452d]">清除篩選</Button><Button onClick={exportLogs} disabled={!rows.length} className="bg-[#70452d]"><Download className="mr-2 h-4 w-4" />匯出稽核紀錄</Button></div></div><Card className={cardClass}><CardContent className="p-0"><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-sm"><thead className="bg-[#faf3eb] text-left text-[#806653]"><tr><th className="p-4"><button type="button" onClick={() => toggleSort("操作時間")} className="font-semibold hover:underline">操作時間（{sortKey === "操作時間" ? sortLabel : "排序"}）</button></th><th className="p-4"><button type="button" onClick={() => toggleSort("員工工號")} className="font-semibold hover:underline">操作員工</button></th><th className="p-4"><button type="button" onClick={() => toggleSort("門市名稱")} className="font-semibold hover:underline">門市</button></th><th className="p-4"><button type="button" onClick={() => toggleSort("動作")} className="font-semibold hover:underline">動作</button></th><th className="p-4"><button type="button" onClick={() => toggleSort("內容")} className="font-semibold hover:underline">內容</button></th><th className="p-4">異動前</th><th className="p-4">異動後</th></tr></thead><tbody>{sortedRows.map((log, index) => <tr key={`${String(log.操作時間)}-${index}`} className="border-t border-[#f0e7df] align-top"><td className="whitespace-nowrap p-4">{顯示日期與星期(String(log.操作時間 ?? "—"))}</td><td className="whitespace-nowrap p-4">{String(log.員工工號 ?? "—")}・{String(log.員工姓名 ?? "—")}</td><td className="p-4">{String(log.門市名稱 ?? log.門市編號 ?? "—")}</td><td className="whitespace-nowrap p-4">{String(log.動作 ?? "—")}</td><td className="p-4">{String(log.內容 ?? "—")}</td><td className="max-w-xs break-all p-4 text-xs text-[#806653]">{String(log.異動前 ?? "—")}</td><td className="max-w-xs break-all p-4 text-xs text-[#806653]">{String(log.異動後 ?? "—")}</td></tr>)}</tbody></table>{!rows.length && <p className="p-10 text-center text-[#a28672]">目前篩選條件沒有操作稽核紀錄。</p>}</div></CardContent></Card></div></Layout></AdminOnly>;
}

export function InventoryTimelinePage() {
  const employees = trpc.admin.listEmployees.useQuery(); const stores = trpc.admin.listAllStores.useQuery();
  const [startDate, setStartDate] = useState(""); const [endDate, setEndDate] = useState(""); const [employeeNo, setEmployeeNo] = useState(""); const [storeId, setStoreId] = useState("");
  const input = useMemo(() => ({ 開始日期: startDate || undefined, 結束日期: endDate || undefined, 員工工號: employeeNo || undefined, 門市編號: storeId ? Number(storeId) : undefined }), [startDate, endDate, employeeNo, storeId]);
  const timeline = trpc.admin.listInventoryTimeline.useQuery(input); const rows = (timeline.data ?? []) as Array<Record<string, unknown>>;
  const clearFilters = () => { setStartDate(""); setEndDate(""); setEmployeeNo(""); setStoreId(""); };
  const exportTimeline = () => 下載CSV(`庫存異動時間軸_${new Date().toISOString().slice(0, 10)}.csv`, [["操作時間", "員工工號", "員工姓名", "門市", "動作", "內容", "異動前", "異動後"], ...rows.map(log => [String(log.操作時間 ?? ""), String(log.員工工號 ?? ""), String(log.員工姓名 ?? ""), String(log.門市名稱 ?? log.門市編號 ?? ""), String(log.動作 ?? ""), String(log.內容 ?? ""), String(log.異動前 ?? ""), String(log.異動後 ?? "")])]);
  return <AdminOnly><Layout title="庫存異動時間軸" description="依日期、員工與門市追蹤共用庫存及四個工作頁的異動內容。"><div className="space-y-6"><Card className={cardClass}><CardContent className="grid gap-4 p-5 md:grid-cols-4"><div><label className="mb-1 block text-sm font-semibold text-[#70452d]">開始日期</label><Input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} /></div><div><label className="mb-1 block text-sm font-semibold text-[#70452d]">結束日期</label><Input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} /></div><div><label className="mb-1 block text-sm font-semibold text-[#70452d]">操作員工</label><Select value={employeeNo || "全部"} onValueChange={value => setEmployeeNo(value === "全部" ? "" : value)}><SelectTrigger><SelectValue placeholder="全部員工" /></SelectTrigger><SelectContent><SelectItem value="全部">全部員工</SelectItem>{(employees.data ?? []).map(employee => <SelectItem key={employee.employeeNo} value={employee.employeeNo}>{employee.employeeNo}・{employee.name}</SelectItem>)}</SelectContent></Select></div><div><label className="mb-1 block text-sm font-semibold text-[#70452d]">操作門市</label><Select value={storeId || "全部"} onValueChange={value => setStoreId(value === "全部" ? "" : value)}><SelectTrigger><SelectValue placeholder="全部門市" /></SelectTrigger><SelectContent><SelectItem value="全部">全部門市</SelectItem>{(stores.data ?? []).map(store => <SelectItem key={store.id} value={String(store.id)}>{store.storeCode}・{store.name}</SelectItem>)}</SelectContent></Select></div></CardContent></Card><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><p className="text-sm text-[#806653]">目前顯示 {rows.length} 筆異動{startDate || endDate ? `，日期 ${startDate || "不限"} 至 ${endDate || "不限"}` : "，全部日期"}{employeeNo ? `，員工 ${employeeNo}` : "，全部員工"}{storeId ? `，門市 ${(stores.data ?? []).find(store => String(store.id) === storeId)?.name ?? storeId}` : "，全部門市"}</p><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={clearFilters} disabled={!startDate && !endDate && !employeeNo && !storeId} className="border-[#dfcbb8] text-[#70452d]">清除篩選</Button><Button onClick={exportTimeline} disabled={!rows.length} className="bg-[#70452d]"><Download className="mr-2 h-4 w-4" />匯出時間軸</Button></div></div><Card className={cardClass}><CardContent className="p-0"><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-sm"><thead className="bg-[#faf3eb] text-left text-[#806653]"><tr><th className="p-4">操作時間</th><th className="p-4">操作員工</th><th className="p-4">門市</th><th className="p-4">動作</th><th className="p-4">異動內容</th><th className="p-4">異動前</th><th className="p-4">異動後</th></tr></thead><tbody>{rows.map((log, index) => <tr key={`${String(log.操作時間)}-${index}`} className="border-t border-[#f0e7df] align-top"><td className="whitespace-nowrap p-4">{顯示日期與星期(String(log.操作時間 ?? "—"))}</td><td className="whitespace-nowrap p-4">{String(log.員工工號 ?? "—")}・{String(log.員工姓名 ?? "—")}</td><td className="p-4">{String(log.門市名稱 ?? log.門市編號 ?? "—")}</td><td className="whitespace-nowrap p-4">{String(log.動作 ?? "—")}</td><td className="p-4">{String(log.內容 ?? "—")}</td><td className="max-w-xs break-all p-4 text-xs text-[#806653]">{String(log.異動前 ?? "—")}</td><td className="max-w-xs break-all p-4 text-xs text-[#806653]">{String(log.異動後 ?? "—")}</td></tr>)}</tbody></table>{!rows.length && <p className="p-10 text-center text-[#a28672]">目前篩選條件沒有庫存異動紀錄。</p>}</div></CardContent></Card></div></Layout></AdminOnly>;
}

export function ItemSummaryPage() {
  const items = trpc.inventory.listItems.useQuery();
  const stores = trpc.admin.listStores.useQuery();
  const itemStores = trpc.admin.listItemStores.useQuery();
  const utils = trpc.useUtils();
  const [selectedByItem, setSelectedByItem] = useState<Record<number, number[]>>({});
  const [keyword, setKeyword] = useState("");
  const [storeFilter, setStoreFilter] = useState("全部");
  const setStores = trpc.admin.setItemStores.useMutation({ onSuccess: () => { toast.success("品項門市設定已保存"); utils.admin.listItemStores.invalidate(); }, onError: error => toast.error(error.message || "品項門市設定失敗") });
  const assignedFor = (itemId: number) => selectedByItem[itemId] ?? (itemStores.data ?? []).filter(row => row.itemId === itemId && row.active).map(row => row.storeId);
  const rows = items.data ?? [];
  const hasUnsavedChanges = rows.some(item => { const current = [...assignedFor(item.id)].sort((a, b) => a - b); const saved = [...(itemStores.data ?? []).filter(row => row.itemId === item.id && row.active).map(row => row.storeId)].sort((a, b) => a - b); return current.join(",") !== saved.join(","); });
  const [saveSummary, setSaveSummary] = useState("");
  useEffect(() => { const handleBeforeUnload = (event: BeforeUnloadEvent) => { if (hasUnsavedChanges) { event.preventDefault(); event.returnValue = ""; } }; window.addEventListener("beforeunload", handleBeforeUnload); return () => window.removeEventListener("beforeunload", handleBeforeUnload); }, [hasUnsavedChanges]);
  const filteredRows = rows.filter(item => {
    const selected = assignedFor(item.id);
    const normalizedKeyword = keyword.trim().toLocaleLowerCase("zh-Hant");
    const matchesKeyword = !normalizedKeyword || `${item.materialCode} ${item.name}`.toLocaleLowerCase("zh-Hant").includes(normalizedKeyword);
    const matchesStore = storeFilter === "全部" || (storeFilter === "未設定門市" ? selected.length === 0 : selected.includes(Number(storeFilter)));
    return matchesKeyword && matchesStore;
  });
  const storeLabel = (storeId: number) => { const store = (stores.data ?? []).find(row => row.id === storeId); return store ? `${store.storeCode}・${store.name}` : String(storeId); };
  const saveAll = async () => { const results = await Promise.allSettled(rows.map(item => setStores.mutateAsync({ 品項編號: item.id, 門市編號: assignedFor(item.id) }))); const failed = results.map((result, index) => result.status === "rejected" ? rows[index].name : null).filter((name): name is string => Boolean(name)); const successCount = results.length - failed.length; setSaveSummary(failed.length ? `已存檔 ${successCount} 項；失敗 ${failed.length} 項：${failed.join("、")}` : `已成功存檔 ${successCount} 項`); if (failed.length) toast.error(`部分存檔失敗：${failed.join("、")}`); else toast.success(`全部存檔成功，共 ${successCount} 項`); };
  const exportSummary = () => {
    const rowsForExport = filteredRows.map(item => {
      const selected = assignedFor(item.id);
      const storeNames = selected.map(storeLabel).join("、") || "未設定門市";
      return [String(item.materialCode), String(item.name), String(item.unitPrice), String(item.largeUnit), String(item.smallUnit), String(item.conversionRatio), storeNames];
    });
    下載CSV(`食包材彙總表_${new Date().toISOString().slice(0, 10)}.csv`, [["貨品代號", "品項名稱", "進貨單價", "大值單位", "小值單位", "換算比例", "設定門市"], ...rowsForExport]);
  };
  return <AdminOnly><Layout title="食包材彙總表" description="以逐行清單查看所有貨物品項；可搜尋、依門市篩選並匯出目前結果。"><Card className={cardClass}><CardHeader><div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between"><CardTitle>所有貨物品項</CardTitle><Button onClick={exportSummary} disabled={!filteredRows.length} className="bg-[#70452d]">匯出彙總表 CSV</Button></div></CardHeader><CardContent className="space-y-4"><div className="grid gap-3 md:grid-cols-[1fr_240px_auto] md:items-end"><div><label htmlFor="item-summary-keyword" className="mb-1 block text-sm font-semibold text-[#70452d]">搜尋品項</label><Input id="item-summary-keyword" value={keyword} onChange={event => setKeyword(event.target.value)} /></div><div><label htmlFor="item-summary-store" className="mb-1 block text-sm font-semibold text-[#70452d]">門市篩選</label><Select value={storeFilter} onValueChange={setStoreFilter}><SelectTrigger id="item-summary-store"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="全部">全部門市</SelectItem><SelectItem value="未設定門市">未設定門市</SelectItem>{(stores.data ?? []).map(store => <SelectItem key={store.id} value={String(store.id)}>{store.storeCode}・{store.name}</SelectItem>)}</SelectContent></Select></div><Button onClick={saveAll} disabled={setStores.isPending || !rows.length} className="bg-[#70452d]">全部存檔</Button></div><div className="flex flex-wrap items-center justify-between gap-2"><p className="text-sm text-[#806653]">目前顯示 {filteredRows.length} / {rows.length} 項</p>{hasUnsavedChanges && <p role="status" className="font-semibold text-[#a4513f]">已有變更尚未存檔</p>}{saveSummary && <p role="status" className="text-sm text-[#806653]">{saveSummary}</p>}</div>{filteredRows.length ? <div className="overflow-x-auto rounded-xl border border-[#eee4da]"><table className="w-full min-w-[980px] text-sm"><thead className="bg-[#faf3eb] text-left text-[#70452d]"><tr><th className="p-3">貨品代號</th><th className="p-3">品項名稱</th><th className="p-3">進貨單價</th><th className="p-3">大小值／換算</th><th className="p-3">設定門市</th><th className="p-3">門市設定</th></tr></thead><tbody>{filteredRows.map(item => { const selected = assignedFor(item.id); return <tr key={item.id} className="border-t border-[#f0e7df] align-top"><td className="whitespace-nowrap p-3 font-semibold text-[#70452d]">{item.materialCode}</td><td className="p-3">{item.name}</td><td className="whitespace-nowrap p-3">{item.unitPrice}</td><td className="whitespace-nowrap p-3">{item.largeUnit}／{item.smallUnit}（{item.conversionRatio}）</td><td className="p-3">{selected.length ? selected.map(storeLabel).join("、") : "未設定門市"}</td><td className="min-w-[280px] p-3"><StoreChecks stores={stores.data ?? []} selected={selected} onChange={ids => setSelectedByItem(previous => ({ ...previous, [item.id]: ids }))} /></td></tr>; })}</tbody></table></div> : <p className="py-10 text-center text-[#a28672]">目前篩選條件沒有符合的品項。</p>}</CardContent></Card></Layout></AdminOnly>;
}

export function StoreSettingsPage() {
  const utils = trpc.useUtils(); const storesQuery = trpc.admin.listAllStores.useQuery();
  const create = trpc.admin.createStore.useMutation({ onSuccess: () => { toast.success("門市已新增"); utils.admin.listStores.invalidate(); setStoreCode(""); setName(""); setAddress(""); }, onError: error => toast.error(error.message || "門市新增失敗") });
  const update = trpc.admin.updateStore.useMutation({ onSuccess: () => { toast.success("門市已更新"); utils.admin.listStores.invalidate(); setEditing(null); }, onError: error => toast.error(error.message || "門市更新失敗") });
  const remove = trpc.admin.deleteStore.useMutation({ onSuccess: () => { toast.success("門市已停用"); utils.admin.listStores.invalidate(); setPendingDelete(null); }, onError: error => toast.error(error.message || "門市刪除失敗") });
  const [storeCode, setStoreCode] = useState(""); const [name, setName] = useState(""); const [address, setAddress] = useState(""); const [editing, setEditing] = useState<any>(null); const [pendingDelete, setPendingDelete] = useState<Store | null>(null);
  return <Layout title="門市管理" description="建立固定五位數字門市代號、門市名稱與地址，並由員工與權限頁指定員工可使用的門市。"><div className="grid gap-6 lg:grid-cols-[.8fr_1.2fr]"><Card className={cardClass}><CardHeader><CardTitle>新增門市</CardTitle></CardHeader><CardContent className="space-y-3"><Input value={storeCode} onChange={e => setStoreCode(e.target.value.replace(/\D/g, "").slice(0, 5))} onBlur={() => setStoreCode(value => value ? 補齊門市代號(value) : value)} placeholder="門市代號（五位數字）" aria-label="門市代號" /><Input value={name} onChange={e => setName(e.target.value)} placeholder="門市名稱" aria-label="門市名稱" /><Input value={address} onChange={e => setAddress(e.target.value)} placeholder="門市地址" aria-label="門市地址" /><p className="text-xs text-[#a28672]">門市代號固定為五位數字，例如 30001。</p><Button disabled={!/^\d{5}$/.test(storeCode) || !name.trim() || !address.trim() || create.isPending} onClick={() => create.mutate({ 門市代號: storeCode, 名稱: name.trim(), 地址: address.trim() })} className="w-full bg-[#70452d]">新增門市</Button></CardContent></Card><Card className={cardClass}><CardHeader><CardTitle>門市清單</CardTitle></CardHeader><CardContent className="space-y-3">{(storesQuery.data ?? []).map(store => editing?.id === store.id ? <div key={store.id} className="space-y-3 rounded-xl border border-[#dfcbb8] p-4"><Input value={editing.storeCode} onChange={e => setEditing({ ...editing, storeCode: e.target.value.replace(/\D/g, "").slice(0, 5) })} onBlur={() => setEditing((previous: any) => previous ? { ...previous, storeCode: previous.storeCode ? 補齊門市代號(previous.storeCode) : previous.storeCode } : previous)} aria-label="修改門市代號" /><Input value={editing.name} onChange={e => setEditing({ ...editing, name: e.target.value })} aria-label="修改門市名稱" /><Input value={editing.address} onChange={e => setEditing({ ...editing, address: e.target.value })} aria-label="修改門市地址" /><div className="flex gap-2"><Button disabled={!/^\d{5}$/.test(editing.storeCode) || !editing.name.trim() || !editing.address.trim()} onClick={() => update.mutate({ 編號: store.id, 門市代號: editing.storeCode, 名稱: editing.name, 地址: editing.address, 啟用: editing.active })} className="bg-[#70452d]">儲存</Button><Button variant="outline" onClick={() => setEditing(null)}>取消</Button></div></div> : <div key={store.id} className="flex flex-col gap-3 rounded-xl border border-[#eee4da] p-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-semibold"><MapPin className="mr-2 inline h-4 w-4 text-[#9b6257]" />{store.storeCode}・{store.name}</p><p className="mt-1 text-sm text-[#806653]">{store.address}</p></div>{pendingDelete?.id === store.id ? <div className="rounded-xl border border-[#e8b7a8] bg-[#fff4ef] p-3 text-sm"><p className="text-[#9b4536]">確定停用「{store.name}」？歷史資料會保留。</p><div className="mt-2 flex flex-wrap gap-2"><Button disabled={remove.isPending} onClick={() => remove.mutate({ 編號: store.id })} className="bg-[#a4513f]">確認停用</Button><Button variant="outline" onClick={() => setPendingDelete(null)}>取消</Button></div></div> : <div className="flex flex-wrap gap-2"><Button variant="outline" onClick={() => setEditing(store)} className="border-[#dfcbb8] text-[#70452d]">修改</Button><Button variant="outline" onClick={() => update.mutate({ 編號: store.id, 門市代號: store.storeCode, 名稱: store.name, 地址: store.address, 啟用: !store.active })} className={store.active ? "border-[#e8b7a8] text-[#a4513f]" : "border-[#b8d8c1] text-[#39734a]"}>{store.active ? <><Trash2 className="mr-1 h-4 w-4" />停用</> : <><Check className="mr-1 h-4 w-4" />啟用</>}</Button></div>}</div>)}{!storesQuery.data?.length && <p className="py-8 text-center text-[#a28672]">目前尚無門市，請先新增。</p>}</CardContent></Card></div></Layout>;
}

function EmployeeSettingsContent() {
  const utils = trpc.useUtils();
  const employees = trpc.admin.listEmployees.useQuery();
  const stores = trpc.admin.listStores.useQuery();
  const assignments = trpc.admin.listEmployeeStores.useQuery();
  const permissionsQuery = trpc.admin.listPermissions.useQuery();
  const create = trpc.admin.createEmployee.useMutation({ onSuccess: () => { toast.success("員工已新增"); utils.admin.listEmployees.invalidate(); setNo(""); setName(""); } });
  const update = trpc.admin.updateEmployee.useMutation({ onSuccess: () => { toast.success("員工資料已更新"); utils.admin.listEmployees.invalidate(); setEditing(null); } });
  const assign = trpc.admin.setEmployeeStores.useMutation({ onSuccess: () => { toast.success("員工門市已更新"); utils.admin.listEmployeeStores.invalidate(); } });
  const updatePermission = trpc.admin.updatePermission.useMutation({ onSuccess: () => { toast.success("作業權限已更新"); utils.admin.listPermissions.invalidate(); }, onError: error => toast.error(error.message || "作業權限更新失敗") });
  const [no, setNo] = useState("");
  const [name, setName] = useState("");
  const [role, setRole] = useState<"admin" | "staff">("staff");
  const [editing, setEditing] = useState<Employee | null>(null);
  const [selected, setSelected] = useState<Record<number, number[]>>({});
  const assignedFor = (id: number) => selected[id] ?? assignments.data?.filter(x => x.員工編號 === id).map(x => x.門市編號) ?? [];
  const operationPermissions = [{ key: "purchase", label: "進貨" }, { key: "return", label: "退貨" }, { key: "scrap", label: "報廢" }, { key: "count", label: "每日盤點" }] as const;
  const permissionFor = (employeeRole: "admin" | "staff", module: string) => permissionsQuery.data?.find(permission => permission.role === employeeRole && permission.module === module);
  const savePermission = (employeeRole: "admin" | "staff", module: typeof operationPermissions[number]["key"], action: "新增" | "修改" | "刪除", value: boolean) => {
    const current = permissionFor(employeeRole, module);
    updatePermission.mutate({ 角色: employeeRole, 模組: module, 新增: action === "新增" ? value : Boolean(current?.canCreate), 修改: action === "修改" ? value : Boolean(current?.canUpdate), 刪除: action === "刪除" ? value : Boolean(current?.canDelete) });
  };
  const toggleEmployee = (employee: Employee) => update.mutate({ 編號: employee.id, 工號: employee.employeeNo, 姓名: employee.name, 角色: employee.role, 啟用: !employee.active });
  return <Layout title="員工與權限" description="管理員工工號、角色、門市分派、帳號狀態與作業權限。停用會保留既有稽核資料。"><div className="space-y-6"><Card className={cardClass}><CardHeader><CardTitle>{editing ? "修改員工" : "新增員工"}</CardTitle></CardHeader><CardContent className="grid gap-3 sm:grid-cols-[1fr_1fr_1fr_auto]">{editing ? <><Input value={editing.employeeNo} onChange={e => setEditing({ ...editing, employeeNo: e.target.value })} placeholder="員工工號" /><Input value={editing.name} onChange={e => setEditing({ ...editing, name: e.target.value })} placeholder="員工姓名" /><Select value={editing.role} onValueChange={v => setEditing({ ...editing, role: v as Employee["role"] })}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="staff">一般員工</SelectItem><SelectItem value="admin">管理員</SelectItem></SelectContent></Select><div className="flex gap-2"><Button disabled={!editing.employeeNo.trim() || !editing.name.trim()} onClick={() => update.mutate({ 編號: editing.id, 工號: editing.employeeNo.trim(), 姓名: editing.name.trim(), 角色: editing.role, 啟用: editing.active })} className="bg-[#70452d]">儲存</Button><Button variant="outline" onClick={() => setEditing(null)}>取消</Button></div></> : <><Input value={no} onChange={e => setNo(e.target.value)} placeholder="員工工號" /><Input value={name} onChange={e => setName(e.target.value)} placeholder="員工姓名" /><Select value={role} onValueChange={v => setRole(v as "admin" | "staff")}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="staff">一般員工</SelectItem><SelectItem value="admin">管理員</SelectItem></SelectContent></Select><Button disabled={!no.trim() || !name.trim()} onClick={() => create.mutate({ 工號: no.trim(), 姓名: name.trim(), 角色: role })} className="bg-[#70452d]"><Plus className="mr-1 h-4 w-4" />新增</Button></>}</CardContent></Card><Card className={cardClass}><CardHeader><CardTitle>員工門市與角色</CardTitle></CardHeader><CardContent className="space-y-4">{(employees.data ?? []).map(employee => { const ids = assignedFor(employee.id); return <div key={employee.id} data-testid="employee-row" className="rounded-xl border border-[#eee4da] p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-semibold">{employee.employeeNo}・{employee.name}</p><p className="text-sm text-[#806653]">{employee.role === "admin" ? "管理員，可管理所有門市" : "一般員工，僅能使用勾選門市"}{!employee.active && "・已停用"}</p></div><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => setEditing(employee)} className="border-[#dfcbb8] text-[#70452d]"><Pencil className="mr-1 h-4 w-4" />修改</Button><Button size="sm" variant="outline" onClick={() => toggleEmployee(employee)} className={employee.active ? "border-[#e8b7a8] text-[#a4513f]" : "border-[#b9d7c2] text-[#2f6b40]"}><Trash2 className="mr-1 h-4 w-4" />{employee.active ? "停用" : "啟用"}</Button><Button size="sm" onClick={() => assign.mutate({ 員工編號: employee.id, 門市編號: ids })} className="bg-[#70452d]"><Check className="mr-1 h-4 w-4" />儲存修改</Button></div></div><div className="mt-3"><StoreChecks stores={(stores.data ?? []) as Store[]} selected={ids} onChange={next => setSelected(prev => ({ ...prev, [employee.id]: next }))} /></div><div className="mt-4 rounded-xl border border-[#d8e5ef] bg-[#f5f9fc] p-3"><p className="mb-2 text-sm font-semibold text-[#42627a]">{employee.role === "admin" ? "管理員作業權限（管理員實際操作不受限制）" : "一般員工作業權限"}</p><div className="grid gap-2 sm:grid-cols-2">{operationPermissions.map(operation => { const permission = permissionFor(employee.role, operation.key); return <div key={operation.key} className="rounded-lg border border-[#dce8f0] bg-white p-2"><p className="mb-2 text-sm font-medium text-[#4d6272]">{operation.label}</p><div className="flex flex-wrap gap-x-3 gap-y-1 text-xs text-[#60778a]">{([['新增', Boolean(permission?.canCreate)], ['修改', Boolean(permission?.canUpdate)], ['刪除', Boolean(permission?.canDelete)]] as const).map(([action, checked]) => <label key={action} className="flex items-center gap-1"><input type="checkbox" checked={checked} onChange={event => savePermission(employee.role, operation.key, action, event.target.checked)} className="h-4 w-4 accent-[#70452d]" />{action}</label>)}</div></div>; })}</div></div></div>; })}{!employees.data?.length && <p className="py-8 text-center text-[#a28672]">目前尚無員工資料，請先新增。</p>}</CardContent></Card></div></Layout>;
}

export function EmployeeSettingsPage() { return <AdminOnly><EmployeeSettingsContent /></AdminOnly>; }

export function ItemSettingsPage() {
  const utils = trpc.useUtils(); const items = trpc.inventory.listItems.useQuery(); const stores = trpc.admin.listStores.useQuery(); const itemStores = trpc.admin.listItemStores.useQuery();
  const create = trpc.inventory.createItem.useMutation({ onSuccess: () => { toast.success("品項已新增"); utils.inventory.listItems.invalidate(); reset(); } }); const update = trpc.inventory.updateItem.useMutation({ onSuccess: () => { toast.success("品項已修改"); utils.inventory.listItems.invalidate(); reset(); } }); const remove = trpc.inventory.deleteItem.useMutation({ onSuccess: () => { toast.success("品項已刪除"); utils.inventory.listItems.invalidate(); } }); const setStores = trpc.admin.setItemStores.useMutation({ onSuccess: () => { toast.success("品項門市設定已保存"); utils.admin.listItemStores.invalidate(); } });
  const [editing, setEditing] = useState<Item | null>(null); const [materialCode, setMaterialCode] = useState(""); const [name, setName] = useState(""); const [price, setPrice] = useState(""); const [large, setLarge] = useState("箱"); const [small, setSmall] = useState("包"); const [ratio, setRatio] = useState("20"); const [selectedStore, setSelectedStore] = useState(""); const [selectedByItem, setSelectedByItem] = useState<Record<number, number[]>>({});
  const reset = () => { setEditing(null); setMaterialCode(""); setName(""); setPrice(""); setLarge("箱"); setSmall("包"); setRatio("20"); }; const formValid = /^[A-Z]\d{6}$/.test(materialCode.trim().toUpperCase()) && name.trim() && Number(price) >= 0 && Number(ratio) > 0; const availableStore = Number(selectedStore) || stores.data?.[0]?.id || 0;
  const assignedFor = (id: number) => selectedByItem[id] ?? itemStores.data?.filter(x => x.itemId === id && x.active).map(x => x.storeId) ?? [];
  const visibleItems = useMemo(() => { if (!availableStore) return items.data ?? []; const rows = items.data ?? []; const hasAssignments = (itemStores.data ?? []).some(x => rows.some(item => item.id === x.itemId)); return hasAssignments ? rows.filter(item => assignedFor(item.id).includes(availableStore)) : rows; }, [items.data, itemStores.data, availableStore, selectedByItem]);
  return <Layout title="食包材品項設定" description="先選擇門市，再管理該門市可使用的食包材品項；新增、修改與刪除均保留管理權限控制。"><div className="space-y-6"><Card className={cardClass}><CardContent className="flex flex-col gap-3 p-5 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-sm font-semibold text-[#70452d]">設定門市</p><p className="mt-1 text-xs text-[#a28672]">只顯示此門市已啟用的品項。</p></div><Select value={selectedStore || (stores.data?.[0]?.id ? String(stores.data[0].id) : "")} onValueChange={setSelectedStore}><SelectTrigger className="w-full bg-white sm:w-64"><SelectValue placeholder="選擇門市" /></SelectTrigger><SelectContent>{(stores.data ?? []).map(store => <SelectItem key={store.id} value={String(store.id)}>{store.storeCode}・{store.name}</SelectItem>)}</SelectContent></Select></CardContent></Card><Card className={cardClass}><CardHeader><CardTitle>品項批次匯入／匯出</CardTitle><p className="mt-2 text-sm text-[#806653]">首次建檔請先下載正式範本，依欄位格式填寫後再匯入。</p><Button variant="outline" onClick={() => 下載CSV("初始品項批次匯入範本.csv", [["貨品代號", "品項名稱", "單價", "大值單位", "小值單位", "換算比例", "初始庫存", "低庫存門檻"], ["", "", "", "", "", "", "", ""]])} className="mt-3 border-[#dfcbb8] text-[#70452d]"><Download className="mr-1 h-4 w-4" />下載初始品項範本</Button></CardHeader><CardContent className="flex flex-wrap gap-2"><Button variant="outline" onClick={() => 下載CSV("食包材品項.csv", [["貨品代號","名稱","單價","大值單位","小值單位","換算比例"], ...(items.data ?? []).map(item => [item.materialCode, item.name, String(item.unitPrice), item.largeUnit, item.smallUnit, String(item.conversionRatio)])])}><Download className="mr-1 h-4 w-4" />匯出品項</Button><label className="inline-flex cursor-pointer items-center rounded-md border border-[#dfcbb8] px-3 py-2 text-sm font-medium text-[#70452d] hover:bg-[#faf3eb]"><Upload className="mr-1 h-4 w-4" />批次匯入品項<input type="file" accept=".csv,text/csv" className="hidden" onChange={async e => { const file = e.target.files?.[0]; if (!file) return; const rows = 解析CSV(await file.text()).slice(1); let count = 0; for (const row of rows) { if (/^[A-Z]\d{6}$/.test((row[0] || "").trim().toUpperCase()) && row[1]?.trim() && Number(row[2]) >= 0 && Number(row[5]) > 0) { await create.mutateAsync({ 貨品代號: row[0].trim().toUpperCase(), 名稱: row[1].trim(), 單價: Number(row[2]), 大值單位: row[3] || "箱", 小值單位: row[4] || "包", 換算比例: Number(row[5]) }); count++; } } toast.success(`已匯入 ${count} 筆品項`); utils.inventory.listItems.invalidate(); e.target.value = ""; }} /></label><p className="basis-full text-xs text-[#a28672]">CSV 欄位：貨品代號、名稱、單價、大值單位、小值單位、換算比例；貨品代號格式為一個英文字母加六個數字。</p></CardContent></Card><Card className={cardClass}><CardHeader><CardTitle>{editing ? "修改品項" : "新增品項"}</CardTitle></CardHeader><CardContent className="grid gap-3 md:grid-cols-5"><div><label className="mb-1 block text-sm font-medium text-[#70452d]">貨品代號</label><Input value={materialCode} onChange={e => setMaterialCode(e.target.value.toUpperCase())} aria-label="貨品代號" /></div><div><label className="mb-1 block text-sm font-medium text-[#70452d]">品項名稱</label><Input value={name} onChange={e => setName(e.target.value)} aria-label="品項名稱" /></div><div><label className="mb-1 block text-sm font-medium text-[#70452d]">進貨單價</label><Input type="number" value={price} onChange={e => setPrice(e.target.value)} aria-label="進貨單價" /></div><div><label className="mb-1 block text-sm font-medium text-[#70452d]">大值單位</label><Input value={large} onChange={e => setLarge(e.target.value)} aria-label="大值單位" /></div><div><label className="mb-1 block text-sm font-medium text-[#70452d]">小值單位</label><Input value={small} onChange={e => setSmall(e.target.value)} aria-label="小值單位" /></div><div><label className="mb-1 block text-sm font-medium text-[#70452d]">換算比例</label><Input type="number" value={ratio} onChange={e => setRatio(e.target.value)} aria-label="換算比例" /></div><div className="flex gap-2 md:col-span-5"><Button disabled={!formValid} onClick={() => { const data = { 貨品代號: materialCode.trim().toUpperCase(), 名稱: name.trim(), 單價: Number(price), 大值單位: large.trim(), 小值單位: small.trim(), 換算比例: Number(ratio) }; editing ? update.mutate({ 編號: editing.id, data }) : create.mutate(data); }} className="bg-[#70452d]">{editing ? "儲存修改" : "新增品項"}</Button>{editing && <Button variant="outline" onClick={reset}>取消</Button>}</div></CardContent></Card><Card className={cardClass}><CardHeader><CardTitle>門市品項清單</CardTitle></CardHeader><CardContent className="space-y-3">{visibleItems.map(item => { const ids = assignedFor(item.id); return <div key={item.id} className="rounded-xl border border-[#eee4da] p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-semibold"><span className="mr-2 rounded bg-[#f2e4d5] px-2 py-1 text-xs text-[#70452d]">{item.materialCode}</span>{item.name}</p><p className="mt-1 text-sm text-[#806653]">單價 ${item.unitPrice}・1 {item.largeUnit} ＝ {item.conversionRatio} {item.smallUnit}</p></div><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => { setEditing(item); setMaterialCode(item.materialCode); setName(item.name); setPrice(String(item.unitPrice)); setLarge(item.largeUnit); setSmall(item.smallUnit); setRatio(String(item.conversionRatio)); }} className="border-[#dfcbb8] text-[#70452d]"><Pencil className="mr-1 h-4 w-4" />修改</Button><Button size="sm" variant="outline" onClick={() => remove.mutate({ 編號: item.id })} className="border-[#e8b7a8] text-[#a4513f]"><Trash2 className="mr-1 h-4 w-4" />刪除</Button><Button size="sm" onClick={() => setStores.mutate({ 品項編號: item.id, 門市編號: ids.includes(availableStore) ? ids.filter(id => id !== availableStore) : [...ids, availableStore] })} className="bg-[#70452d]">{ids.includes(availableStore) ? "移出本門市" : "加入本門市"}</Button></div></div><div className="mt-3"><p className="mb-2 text-xs text-[#a28672]">指定可使用門市</p><StoreChecks stores={(stores.data ?? []) as Store[]} selected={ids} onChange={next => setSelectedByItem(prev => ({ ...prev, [item.id]: next }))} /></div></div>; })}{!visibleItems.length && <p className="py-8 text-center text-[#a28672]">此門市目前沒有可用品項。</p>}</CardContent></Card></div></Layout>;
}

export function TemplateSettingsPage() {
  const utils = trpc.useUtils(); const templates = trpc.admin.listTemplates.useQuery(); const templateStores = trpc.admin.listTemplateStores.useQuery(); const items = trpc.inventory.listItems.useQuery(); const stores = trpc.admin.listStores.useQuery(); const create = trpc.admin.createTemplate.useMutation({ onSuccess: () => { toast.success("預設表單已新增"); utils.admin.listTemplates.invalidate(); setTemplateName(""); setSelectedItems([]); setDefaultUnits({}); } }); const update = trpc.admin.updateTemplate.useMutation({ onSuccess: () => { toast.success("預設表單已修改"); utils.admin.listTemplates.invalidate(); setEditing(null); setDefaultUnits({}); } }); const remove = trpc.admin.deleteTemplate.useMutation({ onSuccess: () => { toast.success("預設表單已刪除"); utils.admin.listTemplates.invalidate(); } }); const setStores = trpc.admin.setTemplateStores.useMutation({ onSuccess: () => { toast.success("預設表單門市設定已保存"); utils.admin.listTemplateStores.invalidate(); } });
  const types = [{ value: "purchase", label: "進貨" }, { value: "return", label: "退貨" }, { value: "scrap", label: "報廢" }, { value: "count", label: "盤點" }] as const; const [active, setActive] = useState<typeof types[number]["value"]>("purchase"); const [templateName, setTemplateName] = useState(""); const [selectedItems, setSelectedItems] = useState<number[]>([]); const [defaultUnits, setDefaultUnits] = useState<Record<number, string>>({}); const [selectedByTemplate, setSelectedByTemplate] = useState<Record<number, number[]>>({}); const [editing, setEditing] = useState<Template | null>(null);
  const templatesForType = (templates.data ?? []).filter(t => t.type === active); const assignedFor = (id: number) => selectedByTemplate[id] ?? templateStores.data?.filter(x => x.templateId === id && x.active).map(x => x.storeId) ?? [];
  return <Layout title="多品項預設表單設定" description="依作業類型建立預設表單，使用勾選框選擇品項，再指定可使用的門市。"><div className="space-y-6"><div className="flex flex-wrap gap-2">{types.map(type => <Button key={type.value} variant={active === type.value ? "default" : "outline"} onClick={() => setActive(type.value)} className={active === type.value ? "bg-[#70452d]" : "border-[#dfcbb8] text-[#70452d]"}>{type.label}</Button>)}</div><Card className={cardClass}><CardHeader><CardTitle>預設表單批次匯入／匯出</CardTitle></CardHeader><CardContent className="flex flex-wrap gap-2"><Button variant="outline" onClick={() => 下載CSV("多品項預設表單.csv", [["類型","名稱","品項編號"], ...(templatesForType).map(template => [template.type, template.name, template.itemIds])])}><Download className="mr-1 h-4 w-4" />匯出預設表單</Button><label className="inline-flex cursor-pointer items-center rounded-md border border-[#dfcbb8] px-3 py-2 text-sm font-medium text-[#70452d] hover:bg-[#faf3eb]"><Upload className="mr-1 h-4 w-4" />批次匯入預設表單<input type="file" accept=".csv,text/csv" className="hidden" onChange={async e => { const file = e.target.files?.[0]; if (!file) return; const rows = 解析CSV(await file.text()).slice(1); let count = 0; for (const row of rows) { const ids = (row[2] || "").split(/[|、;]/).map(Number).filter(Boolean); if (row[1]?.trim() && ids.length) { await create.mutateAsync({ 類型: (row[0] || active) as typeof active, 名稱: row[1].trim(), 品項編號: ids }); count++; } } toast.success(`已匯入 ${count} 張預設表單`); utils.admin.listTemplates.invalidate(); e.target.value = ""; }} /></label><p className="basis-full text-xs text-[#a28672]">CSV 欄位：類型（purchase／return／scrap／count）、名稱、品項編號（以 | 分隔）。</p></CardContent></Card><Card className={cardClass}><CardHeader><CardTitle>{editing ? "修改預設表單" : `新增${types.find(t => t.value === active)?.label}預設表單`}</CardTitle></CardHeader><CardContent className="space-y-4"><Input value={editing?.name ?? templateName} onChange={e => editing ? setEditing({ ...editing, name: e.target.value }) : setTemplateName(e.target.value)} placeholder="預設表單名稱" /><div><p className="mb-2 text-sm font-semibold text-[#70452d]">勾選預設品項</p><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{(items.data ?? []).map(item => <label key={item.id} className="flex flex-wrap items-center gap-2 rounded-lg bg-[#faf3eb] p-2 text-sm"><Checkbox aria-label={`選取${item.name}`} checked={selectedItems.includes(item.id)} onCheckedChange={checked => { setSelectedItems(checked ? [...selectedItems, item.id] : selectedItems.filter(id => id !== item.id)); if (!checked) setDefaultUnits(previous => { const next = { ...previous }; delete next[item.id]; return next; }); }} /><span className="mr-1 text-xs text-[#9b6257]">{item.materialCode}</span><span className="min-w-0 flex-1">{item.name}</span>{selectedItems.includes(item.id) && <span className="flex items-center gap-2 text-xs text-[#806653]"><label className="flex items-center gap-1"><Checkbox aria-label={`${item.name}大值單位`} checked={defaultUnits[item.id] === item.largeUnit} onCheckedChange={checked => setDefaultUnits(previous => ({ ...previous, [item.id]: checked ? item.largeUnit : "" }))} />大值：{item.largeUnit}</label><label className="flex items-center gap-1"><Checkbox aria-label={`${item.name}小值單位`} checked={defaultUnits[item.id] === item.smallUnit} onCheckedChange={checked => setDefaultUnits(previous => ({ ...previous, [item.id]: checked ? item.smallUnit : "" }))} />小值：{item.smallUnit}</label></span>}</label>)}</div></div><Button disabled={!(editing?.name ?? templateName).trim() || !selectedItems.length} onClick={() => { const ids = selectedItems; const 預設單位 = Object.fromEntries(ids.map(id => [String(id), (defaultUnits[id] ?? "").trim()]).filter(([, unit]) => unit)); editing ? update.mutate({ 編號: editing.id, 名稱: editing.name.trim(), 品項編號: ids, 預設單位 }) : create.mutate({ 類型: active, 名稱: templateName.trim(), 品項編號: selectedItems, 預設單位 }); }} className="bg-[#70452d]">{editing ? "儲存修改" : "新增預設表單"}</Button>{editing && <Button variant="outline" onClick={() => setEditing(null)}>取消</Button>}</CardContent></Card><Card className={cardClass}><CardHeader><CardTitle>{types.find(t => t.value === active)?.label}預設表單清單</CardTitle></CardHeader><CardContent className="space-y-4">{templatesForType.map(template => { const ids = assignedFor(template.id); let itemIds: number[] = []; const unitsByItem: Record<number, string> = {}; try { const parsed = JSON.parse(template.itemIds); if (Array.isArray(parsed)) parsed.forEach((entry: unknown) => { const id = typeof entry === "number" ? entry : Number((entry as { 品項編號?: number })?.品項編號); if (Number.isFinite(id)) { itemIds.push(id); if (typeof entry === "object" && entry !== null) unitsByItem[id] = String((entry as { 預設單位?: string }).預設單位 || ""); } }); } catch { itemIds = []; } return <div key={template.id} className="rounded-xl border border-[#eee4da] p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><p className="font-semibold">{template.name}</p><div className="flex gap-2"><Button size="sm" variant="outline" onClick={() => { setEditing(template); try { const parsed = JSON.parse(template.itemIds); const entries = Array.isArray(parsed) && parsed.every((value: unknown) => typeof value === "object" && value !== null && "品項編號" in value) ? parsed as Array<{ 品項編號: number; 預設單位?: string }> : (parsed as number[]).map(品項編號 => ({ 品項編號, 預設單位: "" })); setSelectedItems(entries.map(entry => Number(entry.品項編號))); setDefaultUnits(Object.fromEntries(entries.map(entry => [Number(entry.品項編號), entry.預設單位 ?? ""]))); } catch { setSelectedItems([]); setDefaultUnits({}); } }} className="border-[#dfcbb8] text-[#70452d]"><Pencil className="mr-1 h-4 w-4" />修改</Button><Button size="sm" variant="outline" onClick={() => remove.mutate({ 編號: template.id })} className="border-[#e8b7a8] text-[#a4513f]"><Trash2 className="mr-1 h-4 w-4" />刪除</Button></div></div><p className="mt-1 text-sm text-[#806653]">{(items.data ?? []).filter(i => itemIds.includes(i.id)).map((i, index) => { const unit = unitsByItem[i.id]; const unitLabel = unit ? (unit === i.smallUnit ? `預設小值：${unit}` : `預設大值：${unit}`) : "尚未設定預設單位"; return <React.Fragment key={i.id}>{index > 0 && "、"}<span className="inline-flex flex-wrap items-center gap-1"><span>{i.materialCode} {i.name}</span><span className="rounded border border-[#e8b7a8] bg-[#fff4ef] px-1.5 py-0.5 text-xs text-[#9b4536]">{unitLabel}</span></span></React.Fragment>; }) || "尚未選擇品項"}</p><p className="mt-4 mb-2 text-xs text-[#a28672]">指定可使用門市</p><StoreChecks stores={(stores.data ?? []) as Store[]} selected={ids} onChange={next => { setSelectedByTemplate(prev => ({ ...prev, [template.id]: next })); setStores.mutate({ 表單編號: template.id, 門市編號: next }); }} /></div>; })}{!templatesForType.length && <p className="py-8 text-center text-[#a28672]">目前尚無此類型預設表單。</p>}</CardContent></Card></div></Layout>;
}


export function LoginBrandSettingsPage() {
  const settings = trpc.admin.getBrandSettings.useQuery();
  const update = trpc.admin.updateBrandSettings.useMutation({ onSuccess: () => { toast.success("登入頁面設定已保存"); settings.refetch(); setLogoData(""); }, onError: error => toast.error(error.message) });
  const [companyName, setCompanyName] = useState("顏 水煎餃");
  const [logoData, setLogoData] = useState("");
  useEffect(() => { if (settings.data) setCompanyName(settings.data.公司名稱); }, [settings.data]);
  const previewLogo = logoData || settings.data?.Logo網址 || "/manus-storage/yan-dumpling-logo_9d368cbd.jpeg";
  const handleLogo = (file?: File) => { if (!file) return; if (!file.type.startsWith("image/")) { toast.error("請選擇圖片檔案"); return; } if (file.size > 2 * 1024 * 1024) { toast.error("Logo 圖片不可超過 2 MB"); return; } const reader = new FileReader(); reader.onload = () => setLogoData(String(reader.result || "")); reader.readAsDataURL(file); };
  return <AdminOnly><Layout title="設定登入頁面" description="管理登入頁顯示的公司 Logo 與公司名稱，只有管理員可以修改。"><div className="grid gap-6 lg:grid-cols-[1fr_360px]"><Card className={cardClass}><CardHeader><CardTitle>公司品牌設定</CardTitle></CardHeader><CardContent className="space-y-5"><div><label htmlFor="登入頁公司名稱" className="mb-2 block text-sm font-semibold text-[#70452d]">公司名稱</label><Input id="登入頁公司名稱" value={companyName} onChange={event => setCompanyName(event.target.value)} maxLength={120} /></div><div><label htmlFor="登入頁Logo" className="mb-2 block text-sm font-semibold text-[#70452d]">公司 Logo</label><Input id="登入頁Logo" type="file" accept="image/png,image/jpeg,image/webp" onChange={event => handleLogo(event.target.files?.[0])} /><p className="mt-2 text-xs text-[#806653]">支援 PNG、JPG、WebP，檔案大小上限 2 MB。</p></div><div className="flex flex-wrap gap-2"><Button disabled={!companyName.trim() || update.isPending} onClick={() => update.mutate({ 公司名稱: companyName.trim(), Logo資料: logoData || undefined })} className="bg-[#70452d]">{update.isPending ? "保存中…" : "保存登入頁設定"}</Button></div></CardContent></Card><Card className={cardClass}><CardHeader><CardTitle>登入頁預覽</CardTitle></CardHeader><CardContent className="text-center"><div className="rounded-2xl border border-[#eadfd5] bg-[#faf7f1] p-6"><img src={previewLogo} alt={`${companyName || "公司"} Logo 預覽`} className="mx-auto h-32 w-32 rounded-2xl object-contain shadow-sm" /><p className="mt-4 text-xl font-semibold text-[#70452d]">{companyName || "公司名稱"}</p><p className="mt-1 text-sm text-[#a07a5f]">食包材庫存管理</p></div><p className="mt-4 text-left text-xs text-[#a28672]">最後更新：{settings.data?.更新時間 ? new Date(settings.data.更新時間).toLocaleString("zh-TW") : "尚未設定"}</p></CardContent></Card></div></Layout></AdminOnly>;
}
